function [tau] = torque_authority(m_av, b_min, n_mtq)
%TORQUE_AUTHORITY  The torque the coils give about the worst axis: m B_min min(n, 3)/3 (fewer than three coils
%   leave axes without authority).
%   m_av: real[A m^2] (passed in m^2 A)
%   b_min: real[T] (passed in kg/(s^2 A))
