%   returns tau: real[N m] (passed in m^2 kg/s^2)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    tau = 0;
    h__15 = n_mtq;
    h__16 = 3;
    if h__16 < h__15, h__15 = h__16; end
    tau = (((m_av * b_min) * h__15) / 3);
end
